int 화면글(int молик_объект,int идентификатор_қимат,const uint32_t *иттилоот,unsigned 개수){виҷет_вазъият *너비값=унсур_қимат(молик_объект,идентификатор_қимат);if(!너비값)return -9;if(개수>127)return -22;for(unsigned 순번=0;순번<개수;순번++){unsigned аломат_рамзгузорӣ=иттилоот[순번];if(аломат_рамзгузорӣ>0x10ffff||(аломат_рамзгузорӣ>=0xd800&&аломат_рамзгузорӣ<=0xdfff))return -22;}for(unsigned 순번=0;순번<개수;순번++)너비값->Матн[순번]=иттилоот[순번];너비값->дарозӣ_қимат=개수;if(표시됨(молик_объект,너비값))보드터미널(3);return 0;}
